describe('User Permissions - Edit Content', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display permissions error when trying to edit another user\'s content', () => {
    // Navigate to user profile
    cy.get('[data-testid="user-profile-link"]').click();
    cy.get('[data-testid="user-profile-name"]').should('contain', 'John Doe');

    // Attempt to edit another user's content
    cy.get('[data-testid="edit-content-button"]').click();
    cy.get('[data-testid="edit-form"]').should('be.visible');
    cy.get('[data-testid="user-name-input"]').type('Jane Smith');
    cy.get('[data-testid="user-email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="save-button"]').click();

    // Verify permissions error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'You do not have permission to edit this user\'s content');

    // Verify error styling is applied
    cy.get('[data-testid="error-message"]').should('have.class', 'error');

    // Verify edit form is still visible
    cy.get('[data-testid="edit-form"]').should('be.visible');
  });

  it('should handle successful edit when user has permission', () => {
    // Navigate to user profile
    cy.get('[data-testid="user-profile-link"]').click();
    cy.get('[data-testid="user-profile-name"]').should('contain', 'John Doe');

    // Attempt to edit own content
    cy.get('[data-testid="edit-content-button"]').click();
    cy.get('[data-testid="edit-form"]').should('be.visible');
    cy.get('[data-testid="user-name-input"]').type('John Doe');
    cy.get('[data-testid="user-email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="save-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Content updated successfully');

    // Verify edit form is closed
    cy.get('[data-testid="edit-form"]').should('not.exist');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });
});
